#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_U 10005
#define MAX_PAIRS 1000005

int head[MAX_U];
int to[MAX_PAIRS];
int nxt[MAX_PAIRS];
int edge_cnt = 0;

void add_edge(int u, int card) {
    to[edge_cnt] = card;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main() {
    int N, K, U;
    if (scanf("%d %d %d", &N, &K, &U) != 3) {
        return 0;
    }

    memset(head, -1, sizeof(head));

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j < K; j++) {
            int val;
            scanf("%d", &val);
            add_edge(val, i);
        }
    }

    int hits[1005] = {0};
    int winners[1005];
    int num_winners = 0;

    for (int step = 0; step < U; step++) {
        int drawn;
        scanf("%d", &drawn);

        if (num_winners == 0) {
            for (int e = head[drawn]; e != -1; e = nxt[e]) {
                int card = to[e];
                hits[card]++;
                if (hits[card] == K) {
                    winners[num_winners++] = card;
                }
            }
        }
    }

    qsort(winners, num_winners, sizeof(int), cmp);

    for (int i = 0; i < num_winners; i++) {
        printf("%d%c", winners[i], (i == num_winners - 1) ? '\n' : ' ');
    }

    return 0;
}
